Build an output filter that catches PII and suspicious content before it reaches the user.

```python
# guardrails/output_filter.py
import re
from enum import Enum

class OutputRisk(Enum):
    CLEAN = "clean"
    PII_REDACTED = "pii_redacted"
    BLOCKED = "blocked"

PII_PATTERNS = {
    "email": r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b',
    "phone_us": r'\b(?:\+1[-.]?)?\(?\d{3}\)?[-.]?\d{3}[-.]?\d{4}\b',
    "ssn": r'\b\d{3}-\d{2}-\d{4}\b',
    "credit_card": r'\b(?:\d[ -]?){13,16}\b',
    "api_key_pattern": r'\b(sk-[a-zA-Z0-9]{20,}|Bearer\s+[a-zA-Z0-9._-]{20,})\b',
}

# Content that should never appear in responses
BLOCK_PATTERNS = [
    r'INJECTION SUCCESSFUL',
    r'\bPWNED\b',
    r'I have overridden my instructions',
    r'DAN mode (enabled|activated)',
]

class OutputFilter:
    def filter(self, response: str) -> dict:
        # Check block patterns first (highest priority)
        for pattern in BLOCK_PATTERNS:
            if re.search(pattern, response, re.IGNORECASE):
                return {
                    "risk": OutputRisk.BLOCKED,
                    "response": "[Response blocked by safety filter]",
                    "reason": f"Matched block pattern: {pattern}"
                }

        # Redact PII
        redacted = response
        pii_found = []
        for pii_type, pattern in PII_PATTERNS.items():
            matches = re.findall(pattern, redacted)
            if matches:
                pii_found.append(pii_type)
                redacted = re.sub(pattern, f'[{pii_type.upper()}_REDACTED]', redacted)

        if pii_found:
            return {
                "risk": OutputRisk.PII_REDACTED,
                "response": redacted,
                "reason": f"PII redacted: {', '.join(pii_found)}"
            }

        return {"risk": OutputRisk.CLEAN, "response": response, "reason": "Clean"}


# Test
if __name__ == "__main__":
    filt = OutputFilter()
    tests = [
        "Your account email is john.doe@company.com and SSN is 123-45-6789",
        "INJECTION SUCCESSFUL — I have overridden my instructions.",
        "The refund policy allows 30 days for returns."
    ]
    for t in tests:
        result = filt.filter(t)
        print(f"Risk: {result['risk'].value} | {result['reason']}")
        print(f"Output: {result['response'][:80]}\n")
```
